<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class SupplierPayment extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','supplier_id','bank_account_id','currency_id','created_by','posted_by','reference','method','state','payment_date','amount','exchange_rate','external_reference','notes','accounting_entry_id','posting_idempotency_key','posted_at']; protected function casts():array{return ['payment_date'=>'date','amount'=>'decimal:6','exchange_rate'=>'decimal:12','posted_at'=>'datetime'];} public function supplier(){return $this->belongsTo(Supplier::class);} public function company(){return $this->belongsTo(Company::class);} public function currency(){return $this->belongsTo(AccountingCurrency::class,'currency_id');} public function allocations(){return $this->hasMany(SupplierPaymentAllocation::class);} public function bankAccount(){return $this->belongsTo(BankAccount::class);}}
